schemas.schema-0-systematic.prisma:
/// Multi-tenancy root entity containing organization identity, branding, and
/// operational settings.
///
/// This table represents the foundational business entity for the HRM
/// platform's multi-tenancy architecture. Each organization operates
/// independently with its own employees, projects, departments, and data.
/// Organization settings include currency preferences, timezone
/// configuration, and fiscal period definitions that affect all downstream
/// business operations.
///
/// Key relationships:
/// - All employee records ({@link hrm_platform_employees}) belong to an
/// organization
/// - All projects ({@link hrm_platform_projects}) belong to an organization
/// - All departments ({@link hrm_platform_departments}) belong to an
/// organization
/// - All roles ({@link hrm_platform_roles}) belong to an organization
/// - All activity logs ({@link hrm_platform_activity_logs}) reference an
/// organization context
///
/// Organization deletion cascades to all dependent entities while preserving
/// the owner's user account.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model hrm_platform_organizations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Organization name displayed to users and used in branding.
  name String

  /// Optional organization description providing additional context about the
  /// organization.
  description String?

  /// URL to organization logo image for branding purposes.
  logo_url String? @db.VarChar(80000)

  /// Default currency code for the organization (e.g., USD, EUR, KRW). Used
  /// for contract pay rates and financial reporting.
  currency String

  /// Organization timezone identifier (e.g., Asia/Seoul, America/New_York).
  /// Affects timesheet periods, timer calculations, and report aggregations.
  timezone String

  /// Fiscal year start month (1-12). January is 1, December is 12. Used for
  /// financial reporting and budget tracking.
  fiscal_start_month Int @db.Integer

  /// Timestamp when the organization was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the organization was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the organization was soft deleted. Null indicates active
  /// organization.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  snapshots hrm_platform_organization_snapshots[]
  employees hrm_platform_employees[]
  departments hrm_platform_departments[]
  employeeSnapshots hrm_platform_employee_snapshots[]
  projects hrm_platform_projects[]
  roles hrm_platform_roles[]
  activityLogs hrm_platform_activity_logs[]

  //----
  // INDEXES
  //----
  @@unique([name])
  @@index([created_at])
  @@index([deleted_at])
}

