              "project",
              "time",
              "report",
            ] as const),
            created_at: typia.random<string & tags.Format<"date-time">>(),
            updated_at: typia.random<string & tags.Format<"date-time">>(),
            deleted_at: null,
          }),
        ),
  };
}

