      {
        body: {
          startDate: pastStartDate.toISOString(),
          endDate: pastEndDate.toISOString(),
          groupBy: "project",
          page: 1,
          limit: 20,
        } satisfies IHrmPlatformTimeReport.IRequest,
      },
