  // Fetch full contract with employee summary for response
  const fullContract =
    await MyGlobal.prisma.hrm_platform_contracts.findUniqueOrThrow({
      where: {
        id: props.contractId,
        deleted_at: null,
      },
      select: HrmPlatformContractTransformer.select().select,
